<script setup lang="ts">import { MasonryItem,MasonryRoot,MasonryViewport } from '@fex-design/vue/primitive/masonry';import Button from '@fex-design/vue/ui/button';import { ref } from 'vue';import { masonryItems,type MasonryDemoItem } from './data';const initial=masonryItems.slice(0,8),items=ref([...initial]);let serial=1;function add(middle=false){const item:MasonryDemoItem={id:`added-${serial}`,title:`新增 ${serial}`,height:120+serial%3*40};serial++;const next=[...items.value];next.splice(middle?Math.floor(next.length/2):next.length,0,item);items.value=next}</script>
<template><div class="grid gap-space-md"><div class="flex flex-wrap gap-space-sm"><Button size="sm" @click="add()">末尾添加</Button><Button size="sm" variant="outline" @click="add(true)">中间插入</Button><Button size="sm" variant="outline" @click="items=[...items].sort(()=>Math.random()-.5)">打乱</Button><Button size="sm" variant="outline" @click="items=[...initial]">恢复</Button></div><MasonryRoot :columns="3" :gap="12"><MasonryViewport><MasonryItem v-for="(item,index) in items" :key="item.id" :item-key="item.id" :index="index"><article class="rounded-md border border-border bg-background p-space-md" :style="{minHeight:`${item.height/2}px`}"><strong>{{ item.title }}</strong><p class="text-xs text-muted-foreground">{{ item.id }}</p><Button class="mt-2" size="sm" variant="outline" @click="items=items.filter(value=>value.id!==item.id)">删除</Button></article></MasonryItem></MasonryViewport></MasonryRoot></div></template>
